//! Replays tests/golden/vectors.json (generated by the Python reference).
use gravit_verifier_rs::{verify, Epistemic, Evidence, Registry, TrustRoot};
use serde_json::Value;
use std::{fs, path::PathBuf};

fn golden_path(name: &str) -> PathBuf {
    [env!("CARGO_MANIFEST_DIR"), "..", "tests", "golden", name].iter().collect()
}

fn golden(name: &str) -> Value {
    let p = golden_path(name);
    serde_json::from_str(&fs::read_to_string(&p).unwrap_or_else(|e| panic!("{:?}: {}", p, e))).unwrap()
}

fn trust_root() -> TrustRoot {
    TrustRoot::from_bytes(&fs::read(golden_path("trust_root.json")).unwrap()).expect("valid trust root")
}

fn read_sigs() -> String {
    fs::read_to_string(golden_path("registry.json.sig")).unwrap()
}

fn load_registry(data: &[u8], sigs: &str) -> Result<Registry, String> {
    Registry::from_bytes(data, sigs, &trust_root())
}

#[test]
fn reproduces_every_python_golden_vector() {
    let bindings = golden("bindings.json");
    let bindings = bindings.as_array().expect("bindings array");
    let registry = load_registry(&fs::read(golden_path("registry.json")).unwrap(), &read_sigs()).expect("valid registry");
    let vectors = golden("vectors.json");
    let vectors = vectors.as_array().expect("vectors array");
    assert!(!vectors.is_empty());
    let mut failures = Vec::new();
    for v in vectors {
        let name = v["name"].as_str().unwrap();
        let claimed = v["claimed_state"].as_str().map(|s| Epistemic::from_name(s).expect("known state"));
        let evidence: Vec<Evidence> = v["evidence"].as_array().unwrap().iter().map(Evidence::from_value).collect();
        let reg = if v["use_registry"].as_bool().expect("use_registry") { Some(&registry) } else { None };
        let got = verify(bindings, name, claimed, &evidence, &v["context"], reg);
        if got != v["expected"] {
            failures.push(format!("{}\n  got:      {}\n  expected: {}", name, got, v["expected"]));
        }
    }
    assert!(failures.is_empty(), "{} vector(s) differ:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn registry_changed_after_signing_is_rejected() {
    let text = fs::read_to_string(golden_path("registry.json")).unwrap();
    let mut doc: Value = serde_json::from_str(&text).unwrap();
    doc["verifiers"][0]["key_id"] = Value::String("0".repeat(16));
    // Changing the registry invalidates the root signatures first.
    let err = load_registry(doc.to_string().as_bytes(), &read_sigs()).err().expect("must fail");
    assert!(err.contains("0 valid root signature"), "{}", err);
}

#[test]
fn registry_needs_threshold_of_distinct_root_signatures() {
    let data = fs::read(golden_path("registry.json")).unwrap();
    let sigs = read_sigs();
    let lines: Vec<&str> = sigs.lines().collect();
    assert_eq!(lines.len(), 3);
    let reg = load_registry(&data, &sigs).expect("3 of 5 accepted");
    assert_eq!(reg.signers.len(), 3);
    let two = format!("{}\n{}\n", lines[0], lines[1]);
    let err = load_registry(&data, &two).err().expect("2 of 5 rejected");
    assert!(err.contains("2 valid root signature"), "{}", err);
    let same = format!("{}\n{}\n{}\n", lines[0], lines[0], lines[0]);
    assert!(load_registry(&data, &same).is_err(), "one key three times must not count as three");
}

#[test]
fn trust_root_threshold_must_be_a_majority() {
    let mut doc: Value = serde_json::from_slice(&fs::read(golden_path("trust_root.json")).unwrap()).unwrap();
    doc["threshold"] = Value::from(2); // 2 of 5
    let err = TrustRoot::from_bytes(doc.to_string().as_bytes()).err().expect("must fail");
    assert!(err.contains("more than half"), "{}", err);
}

#[test]
fn timestamp_parser_matches_python_reference_values() {
    use gravit_verifier_rs::parse_utc_timestamp as p;
    // Expected values computed with Python's calendar.timegm.
    assert_eq!(p("1970-01-01T00:00:00Z"), Some(0));
    assert_eq!(p("2000-02-29T00:00:00Z"), Some(951782400));
    assert_eq!(p("0001-01-01T00:00:00Z"), Some(-62135596800));
    assert_eq!(p("9999-12-31T23:59:59Z"), Some(253402300799));
    assert_eq!(p("2026-09-06T13:00:00Z"), Some(1788699600));
    for bad in [
        "2026-02-29T00:00:00Z", "1900-02-29T00:00:00Z", "2026-13-01T00:00:00Z",
        "2026-01-01T24:00:00Z", "2026-01-01T00:00:60Z", "2026-01-01 00:00:00Z",
        "２026-01-01T00:00:00Z", "2026-01-01T00:00:00", "",
    ] {
        assert_eq!(p(bad), None, "{:?}", bad);
    }
}

#[test]
fn jcs_numbers_match_rfc8785() {
    use gravit_verifier_rs::jcs_number;
    let cases: [(f64, &str); 14] = [
        (1e21, "1e+21"), (1e-7, "1e-7"), (1e-6, "0.000001"), (1.2345678901234568e20, "123456789012345680000"),
        (4.5, "4.5"), (0.002, "0.002"), (2.0 / 3.0, "0.6666666666666666"), (1.0, "1"), (-0.0, "0"),
        (5e-324, "5e-324"), (1.7976931348623157e308, "1.7976931348623157e+308"), (-1.5e-9, "-1.5e-9"),
        (100.0, "100"), (123.456, "123.456"),
    ];
    for (x, want) in cases {
        assert_eq!(jcs_number(x), want, "{}", x);
    }
}
